// ═══ UNSAFE PUBLICATION — other thread sees partial object! ═══
class UnsafePublisher {
    static Account account;  // NOT volatile!

    static void initialize() {
        account = new Account("SAV2001", new BigDecimal("100000"));
        // Thread-2 may see: account != null BUT account.balance == null!
        // WHY? The JVM/CPU may reorder:
        // 1. Allocate memory for Account
        // 2. Write reference to 'account' (non-null!) ← published HERE!
        // 3. Run constructor (set fields)              ← fields set AFTER publication!
        // Thread-2 reads 'account' between step 2 and 3 → sees nulls!
    }
}

// ═══ SAFE 1: final fields (best for immutable objects!) ═══
class Account {
    final String id;                 // final → guaranteed visible after constructor
    final BigDecimal initialBalance; // final → guaranteed visible

    Account(String id, BigDecimal balance) {
        this.id = id;
        this.initialBalance = balance;
    }
    // JMM guarantee: when the constructor completes, ALL final fields are
    // visible to any thread that obtains a reference to this object.
    // Even without volatile or synchronized!
}

// ═══ SAFE 2: volatile reference ═══
class SafePublisher {
    static volatile Account account;  // volatile!

    static void initialize() {
        Account temp = new Account("SAV2001", new BigDecimal("100000"));
        account = temp;  // volatile write → happens-before → all fields visible!
    }
    // Thread-2: reads volatile 'account' → guaranteed to see fully-constructed object
}

// ═══ SAFE 3: synchronized block ═══
class SyncPublisher {
    static Account account;
    static final Object lock = new Object();

    static void initialize() {
        synchronized (lock) {
            account = new Account("SAV2001", new BigDecimal("100000"));
        }
    }
    static Account getAccount() {
        synchronized (lock) { return account; }  // happens-before!
    }
}

// ═══ SAFE 4: thread-safe collection ═══
ConcurrentHashMap<String, Account> accounts = new ConcurrentHashMap<>();
accounts.put("SAV2001", new Account("SAV2001", new BigDecimal("100000")));
// CHM.put() has built-in happens-before → readers see fully-constructed Account

// ═══ DOUBLE-CHECKED LOCKING (classic safe publication) ═══
class Singleton {
    private static volatile Singleton instance;  // MUST be volatile!

    static Singleton getInstance() {
        if (instance == null) {                  // first check (no lock)
            synchronized (Singleton.class) {
                if (instance == null) {           // second check (with lock)
                    instance = new Singleton();   // volatile write → safe publication!
                }
            }
        }
        return instance;
    }
    // Without volatile: another thread may see non-null 'instance' with
    // uninitialized fields (instruction reordering)!
}
