// ─── File: src/test/java/com/bank/publish/SafePublicationTest.java ───
package com.bank.publish;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class SafePublicationTest {

    // Immutable object with final fields — safe to publish via any mechanism
    record Account(String id, BigDecimal balance) {}

    // ═══ SAFE: final fields ═══
    @Test
    void finalFields_alwaysFullyVisible() throws InterruptedException {
        Account[] holder = {null};
        CountDownLatch published = new CountDownLatch(1);

        Thread writer = new Thread(() -> {
            holder[0] = new Account("SAV2001", new BigDecimal("100000"));
            published.countDown();
        });
        writer.start();
        published.await();

        // Record fields are final → guaranteed visible after constructor
        assertThat(holder[0].id()).isEqualTo("SAV2001");
        assertThat(holder[0].balance()).isEqualByComparingTo("100000");
    }

    // ═══ SAFE: volatile reference ═══
    static volatile Account volatileAccount;

    @Test
    void volatileReference_safePublication() throws InterruptedException {
        Thread writer = new Thread(() -> {
            volatileAccount = new Account("CUR3001", new BigDecimal("250000"));
        });
        writer.start();
        writer.join();

        // volatile write happens-before volatile read → all fields visible
        assertThat(volatileAccount.id()).isEqualTo("CUR3001");
        assertThat(volatileAccount.balance()).isEqualByComparingTo("250000");
    }

    // ═══ SAFE: ConcurrentHashMap ═══
    @Test
    void concurrentHashMap_safePublication() throws InterruptedException {
        ConcurrentHashMap<String, Account> cache = new ConcurrentHashMap<>();

        Thread writer = new Thread(() -> {
            cache.put("SAV2001", new Account("SAV2001", new BigDecimal("100000")));
        });
        writer.start();
        writer.join();

        Account acc = cache.get("SAV2001");
        assertThat(acc).isNotNull();
        assertThat(acc.id()).isEqualTo("SAV2001");
        assertThat(acc.balance()).isEqualByComparingTo("100000");
    }

    // ═══ SAFE: Double-checked locking with volatile ═══
    static class ConfigSingleton {
        private static volatile ConfigSingleton instance;
        final String dbUrl;
        final int poolSize;

        private ConfigSingleton() {
            dbUrl = "jdbc:postgresql://localhost/bank";
            poolSize = 20;
        }

        static ConfigSingleton getInstance() {
            if (instance == null) {
                synchronized (ConfigSingleton.class) {
                    if (instance == null) {
                        instance = new ConfigSingleton();  // volatile write!
                    }
                }
            }
            return instance;
        }
    }

    @Test
    void doubleCheckedLocking_safePublication() throws InterruptedException {
        AtomicReference<ConfigSingleton> result = new AtomicReference<>();
        int threads = 20;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int i = 0; i < threads; i++) {
            new Thread(() -> {
                result.set(ConfigSingleton.getInstance());
                latch.countDown();
            }).start();
        }
        latch.await();

        ConfigSingleton config = ConfigSingleton.getInstance();
        assertThat(config.dbUrl).isEqualTo("jdbc:postgresql://localhost/bank");
        assertThat(config.poolSize).isEqualTo(20);  // fully constructed!
    }
}
